function buildingsPanel(){showPanel(`<div class="row"><div><div class="eyebrow">다시 돌아올 곳</div><h2>피난처 재건</h2></div><button id="back">뒤로</button></div><p class="gold">◈ ${save.gold} 금화 · ${save.wood} 목재 · ${save.stone} 석재 · ${save.iron} 철광석</p><div class="grid">${BUILDINGS.map(b=>{let n=save.buildings[b.id],cost=Math.round(b.cost*Math.pow(1.65,n)),wood=b.wood*(n+1),stone=b.stone*(n+1),iron=n>=2?n-1:0,locked=b.id!=='guild'&&n>=2+save.buildings.guild*2,can=n<b.max&&!locked&&save.gold>=cost&&save.wood>=wood&&save.stone>=stone&&save.iron>=iron;return `<div class="card"><span class="glyph">${b.icon}</span><h3>${b.name}</h3><span class="pill">레벨 ${n} / ${b.max}</span><p>${b.text}</p><p class="gold">${n===b.max?'최고 단계 건설 완료':`${cost} 금화 · ${wood} 목재<br>${stone} 석재${iron?' · '+iron+' 철광석':''}`}</p><button data-upgrade="${b.id}" ${can?'':'disabled'}>${n===b.max?'완료':locked?'길드 회관 강화 필요':'건설 / 강화'}</button></div>`;}).join('')}</div><p class="muted">건설 효과는 모든 영웅이 공유합니다. 길드 회관으로 전문화와 상위 건설 단계가 열립니다.</p>`);bind('back',townPanel);document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{let v=BUILDINGS.find(x=>x.id===b.dataset.upgrade),n=save.buildings[v.id],cost=Math.round(v.cost*1.65**n);if(save.gold<cost)return;save.gold-=cost;save.wood-=v.wood*(n+1);save.stone-=v.stone*(n+1);if(n>=2)save.iron-=n-1;save.buildings[v.id]++;sound('level');persist();buildingsPanel();notify(v.name+' 건설·강화 완료');});}
function gearText(g){return '+'+(g.stat==='crit'?Math.round(equipmentValue(g)*100)+'%':Number(equipmentValue(g).toFixed(1)))+' '+({damage:'공격력',hp:'최대 체력',armor:'방어력',mana:'최대 마나',crit:'치명타 확률'}[g.stat]);}
function createGear(quality=0,forcedSlot=null){let slot=forcedSlot||choice(['weapon','armor','charm']),tier=Math.min(5,Math.floor(run.floor/2)+quality+Math.floor(Math.random()*2)),rarity=tier>=4?'legendary':tier>=2?'epic':tier>=1?'rare':'common',stat=slot==='weapon'?'damage':slot==='armor'?'armor':choice(['hp','mana','crit']),value=stat==='damage'?4+tier*3:stat==='armor'?2+tier:stat==='crit'?.03+tier*.015:15+tier*8;let g={id:'g'+Date.now()+Math.random().toString(36).slice(2,6),slot,stat,value,baseValue:value,upgrade:0,ilvl:1+run.floor*3+tier,affix:tier>=1?choice(AFFIXES).id:null,name:GEAR_NAMES[slot][tier],rarity};save.gear.push(g);let old=save.gear.find(x=>x.id===save.equipped[slot]);latestDrop=g.id;celebrate('새 장비 발견',legacyGearName(g.name,g.slot)+' · '+gearText(g)+' · Tab으로 비교·장착',rarityColor(rarity));notify(`${legacyGearName(g.name,g.slot)} 획득 · Tab으로 비교·장착하세요.`);persist();return g;}
function relicPanel(source=null){let pool=RELICS.filter(r=>!run.relics.includes(r.id)),options=source?.relicOffers?source.relicOffers.map(id=>pool.find(r=>r.id===id)).filter(Boolean):pool.sort(()=>Math.random()-.5).slice(0,3);if(source&&!source.relicOffers){source.relicOffers=options.map(r=>r.id);persist();}if(!options.length){run.gold+=100;if(source)source.used=true;notify('유물함에서 금화 100을 얻었습니다.');persist();return;}showPanel(`<div class="eyebrow">잊힌 시대의 유산</div><h2>유물 선택</h2><p>이번 원정에서만 효과가 유지됩니다. 닫아도 다시 선택할 수 있습니다.</p><div class="grid" style="grid-template-columns:repeat(${options.length},1fr)">${options.map(r=>`<button class="card" data-relic="${r.id}"><span class="glyph">✦</span><h3>${r.name}</h3><p>${r.text}</p></button>`).join('')}</div>`);document.querySelectorAll('[data-relic]').forEach(b=>b.onclick=()=>{let r=RELICS.find(r=>r.id===b.dataset.relic);if(!r||source?.used||run.relics.includes(r.id))return;run.relics.push(r.id);if(source)source.used=true;if(r.stat==='hp')p.hp+=r.value;if(r.stat==='mana')p.mana+=r.value;sound('level');closePanel();notify(r.name+' 획득');persist();});}
function rarityColor(r){return {common:'#b9bcae',rare:'#73b9e9',epic:'#b893e2',legendary:'#e4b468'}[r]||'#b9bcae';}
function celebrate(title,detail,color='#e2c384'){celebration={title,detail,color,left:3.4};sound('level');}
function recordGrowth(title,detail){save.growthLog.unshift({title,detail,at:Date.now()});save.growthLog=save.growthLog.slice(0,12);celebrate(title,detail);persist();}
function growthFeedback(){let last=save.growthLog[0];return last&&Date.now()-last.at<20000?`<div class="growth-receipt"><strong>${last.title}</strong><span>${last.detail}</span></div>`:'';}
function statStrip(){let s=stats();return `<div class="stat-strip"><span><b>${Math.round(s.damage)}</b>공격력</span><span><b>${Math.round(s.hp)}</b>체력</span><span><b>${Math.round(s.mana)}</b>마나</span><span><b>${s.armor.toFixed(1)}</b>방어력</span><span><b>${Math.round(s.crit*100)}%</b>치명타</span></div>`;}
function trainingPanel(){let h=hero(),c=cls(),limit=rankLimit(save),fromTown=mode==='town';showPanel(`<div class="row"><div><div class="eyebrow">${c.name} · 영구 성장</div><h2>훈련장</h2></div><button id="trainBack">${fromTown?'피난처로':'계속하기'}</button></div>${statStrip()}${growthFeedback()}<div class="progress-summary"><span><b>${h.skillPoints}</b> 기술 포인트</span><span><b>${h.attributePoints}</b> 능력치 포인트</span><span>레벨 ${h.level} · 최대 기술 등급 ${limit}/5</span></div><p>레벨마다 기술·능력치 포인트를 각각 3점 얻습니다. 새 기술을 배우거나 기존 기술을 강화하세요. 3등급에서는 기술의 범위나 사용 방식이 진화합니다.</p><div class="skill-tree">${['q','e','passive','ultimate'].map(key=>{let r=h.skills[key]||0,cost=skillPrice(h,key),locked=key==='ultimate'&&h.level<10,name=key==='q'?c.q:key==='e'?c.e:key==='passive'?'영웅의 결의':c.specs[h.spec]+' 기술',can=!locked&&r<limit&&h.skillPoints>=cost;return `<article class="skill-node ${r?'learned':''}"><div class="row"><span class="skill-key">${{q:'Q',e:'E',passive:'◆',ultimate:'C'}[key]}</span><span class="rank-dots">${'●'.repeat(r)}${'○'.repeat(5-r)}</span></div><h3>${name}</h3><p>${r?skillDescription(c.id,key,r):'아직 배우지 않음'}</p><div class="next-rank"><span class="eyebrow">${r>=5?'최고 등급':'다음 등급: '+(r+1)}</span><p>${r>=5?'최고 등급에 도달했습니다.':skillDescription(c.id,key,r+1)}</p></div><button class="${can?'primary':''}" data-train="${key}" ${can?'':'disabled'}>${locked?'영웅 10레벨 필요':r>=5?'최고 등급':r>=limit?'훈련장 단계 '+(limit-1)+' 필요':`${r?'강화':'습득'} · ${cost}점`}</button></article>`;}).join('')}</div>${warriorStyleMarkup()}<div class="divider"></div><h3>능력치 선택</h3><div class="attribute-list">${ATTRIBUTE_DEFS.map(a=>`<div class="attribute-row"><div><b>${a.name}</b><small>${a.text}</small></div><strong>${h.attributes[a.id]}</strong><button data-attribute="${a.id}" ${h.attributePoints?'':'disabled'}>+1</button></div>`).join('')}</div><p class="muted">원정 중에도 K로 훈련할 수 있습니다. 상위 기술 등급은 피난처 건설이 필요합니다. 전문화는 10레벨과 길드 회관 1단계에서 열립니다.</p>`);bind('trainBack',()=>fromTown?townPanel():closePanel());document.querySelectorAll('[data-train]').forEach(b=>b.onclick=()=>{let key=b.dataset.train,result=trainSkill(save,h,key);if(result.ok){let name=key==='q'?c.q:key==='e'?c.e:key==='passive'?'영웅의 결의':'전문화';recordGrowth(result.before?'기술 강화':'새 기술 습득',`${name} · 등급 ${result.after}${result.after===3?' · 진화':''}`);trainingPanel();updateHud();}});document.querySelectorAll('[data-attribute]').forEach(b=>b.onclick=()=>{if(allocateAttribute(h,b.dataset.attribute)){persist();trainingPanel();updateHud();}});}
function itemTitle(g){return `${g.affix?AFFIXES.find(a=>a.id===g.affix)?.name+' ':''}${legacyGearName(g.name,g.slot)}${g.upgrade?' +'+g.upgrade:''}`;}
function itemCard(g,label,comparison=null){if(!g)return `<div class="gear-detail empty"><div class="eyebrow">${label}</div><h3>기본 장비</h3><p>추가 능력치 없음</p></div>`;let delta=comparison&&comparison.stat===g.stat?equipmentValue(g)-equipmentValue(comparison):equipmentValue(g),affix=AFFIXES.find(a=>a.id===g.affix);return `<div class="gear-detail ${g.rarity}"><div class="eyebrow">${label} · ${KO_SLOT[g.slot]} · 장비 레벨 ${g.ilvl}</div><canvas class="item-icon" width="64" height="64" data-icon="${g.slot}" data-rarity="${g.rarity}"></canvas><h3>${itemTitle(g)}</h3><span class="pill">${KO_RARITY[g.rarity]}</span><p class="gear-number">${gearText(g)}</p>${comparison?`<p class="${delta>=0?'positive':'negative'}">${delta>=0?'+':''}${g.stat==='crit'?Math.round(delta*100)+'%':delta.toFixed(1)} · 현재 장비 대비</p>`:''}${affix?`<div class="affix"><b>${affix.name}</b><p>${affix.text}</p></div>`:''}<div class="upgrade-pips">${'◆'.repeat(g.upgrade||0)}${'◇'.repeat(5-(g.upgrade||0))}</div></div>`;}
function inventoryPanel(fromTown=mode==='town'){let selectedGear=save.gear.find(g=>g.id===inspectedGear)||save.gear.find(g=>g.id===latestDrop)||save.gear.at(-1),equipped=selectedGear?save.gear.find(g=>g.id===save.equipped[selectedGear.slot]):null,q=selectedGear?forgeQuote(selectedGear):null;showPanel(`<div class="row"><div><div class="eyebrow">영구 장비 · 보관 자원 ${save.gold} 금화 / ${save.stone} 석재 / ${save.iron} 철광석</div><h2>장비 · 대장간</h2></div><button id="gearBack">${fromTown?'피난처로':'계속하기'}</button></div>${statStrip()}${growthFeedback()}<div class="armory-layout"><aside><h3>장착 중</h3>${['weapon','armor','charm'].map(slot=>{let g=save.gear.find(g=>g.id===save.equipped[slot]);return `<button class="equipped-slot" data-inspect="${g?.id||''}"><canvas class="item-icon" width="48" height="48" data-icon="${slot}" data-rarity="${g?.rarity||'common'}"></canvas><span><small>${KO_SLOT[slot]}</small><b>${g?itemTitle(g):'기본 '+KO_SLOT[slot]}</b><small>${g?gearText(g):'추가 능력치 없음'}</small></span></button>`;}).join('')}<h3 style="margin-top:20px">보유 장비 · ${save.gear.length}</h3><div class="inventory-grid">${save.gear.slice().reverse().map(g=>`<button title="${itemTitle(g)} · ${gearText(g)}" aria-label="${itemTitle(g)} 살펴보기" class="gear-tile ${g.rarity} ${selectedGear?.id===g.id?'selected':''}" data-inspect="${g.id}"><canvas class="item-icon" width="48" height="48" data-icon="${g.slot}" data-rarity="${g.rarity}"></canvas><small>${g.upgrade?'+'+g.upgrade:'Lv '+g.ilvl}</small>${save.equipped[g.slot]===g.id?'<i>●</i>':''}</button>`).join('')}</div></aside><section>${selectedGear?`<div class="comparison">${itemCard(equipped,'장착 중')}${itemCard(selectedGear,'선택 장비',equipped)}</div><div class="row wrap gear-actions"><button class="primary" id="equipSelected" ${equipped?.id===selectedGear.id?'disabled':''}>${equipped?.id===selectedGear.id?'장착 중':KO_SLOT[selectedGear.slot]+' 장착'}</button><button id="forgeSelected" ${!fromTown||selectedGear.upgrade>=5||selectedGear.upgrade>=1+save.buildings.forge||save.gold<q.gold||save.stone<q.stone||save.iron<q.iron?'disabled':''}>강화 +${selectedGear.upgrade+1}</button></div><p class="forge-cost">${!fromTown?'피난처에서 강화할 수 있습니다.':selectedGear.upgrade>=5?'최대 강화':`다음 강화: ${gearText({...selectedGear,upgrade:selectedGear.upgrade+1})} · 필요 자원: ${q.gold} 금화 + ${q.stone} 석재${q.iron?' + '+q.iron+' 철광석':''}`}</p><p class="muted">피난처에서 첫 강화를 진행할 수 있습니다. 대장간 단계가 오르면 추가 강화가 열립니다. 강화와 원소 특성은 쓰러져도 유지됩니다.</p>`:'<div class="gear-detail empty"><h3>첫 무기를 찾아보세요</h3><p>첫 원정 상자에는 무기가 반드시 있습니다. F로 열고 Tab에서 비교한 뒤 직접 장착하세요.</p></div>'}<h3>이번 원정의 유물</h3><p>${(run?.relics||[]).map(id=>RELICS.find(r=>r.id===id)?.name).join(' · ')||'아직 획득한 유물이 없습니다.'}</p></section></div>`);bind('gearBack',()=>fromTown?townPanel():closePanel());document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>{if(b.dataset.inspect){inspectedGear=b.dataset.inspect;inventoryPanel(fromTown);}});bind('equipSelected',()=>{if(!selectedGear)return;const before=stats().damage;save.equipped[selectedGear.slot]=selectedGear.id;recordGrowth('장비 장착',itemTitle(selectedGear)+' · '+gearText(selectedGear));inventoryPanel(fromTown);updateHud();});bind('forgeSelected',()=>{if(!fromTown||!selectedGear)return;let result=forgeGear(save,selectedGear);if(result.ok){recordGrowth('장비 강화 완료',itemTitle(selectedGear)+` · ${result.before.toFixed(1)} → ${result.after.toFixed(1)}`);inventoryPanel(true);}});drawItemIcons();}
function drawItemIcons(){document.querySelectorAll('canvas.item-icon').forEach(c=>{let x=c.getContext('2d'),s=c.width/32;x.imageSmoothingEnabled=false;x.scale(s,s);x.fillStyle='#101820';x.fillRect(0,0,32,32);x.fillStyle=rarityColor(c.dataset.rarity);if(c.dataset.icon==='weapon'){x.save();x.translate(16,16);x.rotate(.7);x.fillStyle='#d5dfd0';x.fillRect(-2,-13,4,20);x.fillStyle='#8b9da1';x.fillRect(-2,-13,2,20);x.fillStyle='#d9ad59';x.fillRect(-7,5,14,3);x.fillStyle='#846149';x.fillRect(-2,8,4,7);x.restore();}else if(c.dataset.icon==='armor'){x.fillRect(8,7,16,20);x.fillRect(4,6,8,7);x.fillRect(20,6,8,7);x.fillStyle='#1a2429';x.fillRect(12,5,8,6);x.fillRect(15,12,2,14);x.fillStyle='#d4c081';x.fillRect(9,22,14,3);}else{x.beginPath();x.moveTo(16,5);x.lineTo(26,16);x.lineTo(16,28);x.lineTo(6,16);x.closePath();x.fill();x.fillStyle='#d9b56a';x.fillRect(14,10,4,13);x.fillStyle='#f4e6b3';x.fillRect(12,14,8,4);}});}
function orbPanel(source=null){let options=[{id:'q_power',title:cls().q+' · 위력',text:'이번 원정 Q 피해 +35%'},{id:'q_shape',title:cls().q+' · 진화',text:'Q의 3등급 진화 형태를 이번 원정에서 미리 사용'},{id:'flow',title:'마력의 흐름',text:'이번 원정 기술 재사용 대기시간 20% 감소'}].filter(o=>!(run.orbs||[]).includes(o.id));if(!options.length){p.mana=stats().mana;if(source)source.used=true;notify('구체가 마나를 회복했습니다.');persist();return;}showPanel(`<div class="eyebrow">기술 구체 · 이번 원정 한정</div><h2>기술 강화 선택</h2><div class="grid" style="grid-template-columns:repeat(${options.length},1fr)">${options.map(o=>`<button class="card" data-orb="${o.id}"><span class="glyph">✦</span><h3>${o.title}</h3><p>${o.text}</p></button>`).join('')}</div>`);document.querySelectorAll('[data-orb]').forEach(b=>b.onclick=()=>{run.orbs??=[];if(source?.used||run.orbs.includes(b.dataset.orb))return;run.orbs.push(b.dataset.orb);if(source)source.used=true;closePanel();celebrate('구체의 힘 획득',options.find(o=>o.id===b.dataset.orb).title);persist();});}
function showTrainingDummy(){showPanel(`<div class="eyebrow">연습 허수아비 · 보상 없음 / 피해 없음</div><h2>공격 성능 확인</h2><p>평소처럼 허수아비를 공격해 실제 피해량을 확인하세요. 장비나 능력치를 바꾼 뒤 다음 타격을 비교할 수 있습니다.</p>${statStrip()}${growthFeedback()}<p class="gold">최근 피해: ${dummyRecord.last} · 최고 피해: ${dummyRecord.best} · 타격 횟수: ${dummyRecord.hits}</p><div class="row"><button id="dummyBack">계속 연습</button><button id="dummyTrain">기술 훈련</button></div>`,true);bind('dummyBack',closePanel);bind('dummyTrain',trainingPanel);}

function finishRun(won=false,abandon=false){
 if(!run)return;fantasyAudio.cancel?.('heroAttack');const keep=retentionRate(save,won),earned={};for(let k of ['gold','wood','stone','iron']){earned[k]=Math.floor(run[k]*keep);save[k]+=earned[k];}
 save.totalKills+=run.kills;const summary={...run},h=hero();if(won){save.wins++;save.bosses=Math.max(save.bosses,3);}
 const receipt={at:Date.now(),classId:save.classId,outcome:won?'win':abandon?'retreat':'death',depth:summary.floor+1,kills:summary.kills,seconds:Math.floor(summary.seconds),earned,level:h.level,levels:Math.max(0,h.level-(summary.startLevel||h.level)),gear:Math.max(0,save.gear.length-(summary.startGear??save.gear.length))};
 save.runHistory=[receipt,...(save.runHistory||[])].slice(0,5);run=null;p=null;save.run=null;persist();mode='town';sound(won?'level':'die');
 showPanel(`<div class="eyebrow">${won?'왕관을 무너뜨렸습니다':abandon?'다음 도전을 준비하며':'쓰러져도 성장은 남습니다'}</div><h1>${won?'다시 밝아오는 새벽':'피난처로 돌아왔습니다'}</h1><p>${won?'공허한 왕을 쓰러뜨렸습니다. 다음 원정부터 더 강한 적에게 도전할 수 있습니다.':`소지 자원의 ${Math.round(keep*100)}%를 가져왔습니다. 이미 운반꾼에게 맡긴 자원은 손실 없이 보관됩니다.`}</p><div class="run-results"><article><strong>${receipt.depth}층</strong><span>도달 지점</span></article><article><strong>${receipt.kills}</strong><span>처치한 적</span></article><article><strong>${Math.floor(receipt.seconds/60)}분 ${receipt.seconds%60}초</strong><span>원정 시간</span></article><article><strong>${h.level}레벨</strong><span>${cls().name} · 이번 성장 +${receipt.levels}</span></article></div><section class="kept-rewards"><h3>다음 원정에도 남는 것</h3><p>${resourceLine(earned)}</p><p>새 장비 ${receipt.gear}개 · 모든 장비와 경험치 · 피난처 건설</p></section><p class="muted">이번 원정의 유물·구체 효과는 끝났습니다. 새 원정에서 다른 조합을 선택할 수 있습니다.</p>${journeyGoalMarkup()}<div class="row wrap"><button class="primary" id="returnTown">성장 확인 · 피난처</button><button id="retryRun">같은 영웅으로 다시 도전</button></div>`);
 bind('returnTown',townPanel);bind('retryRun',beginRun);
}

function solid(x,y,r=11){for(let dy of [-r,r])for(let dx of [-r,r])if(!map.tiles[Math.floor((y+dy)/T)]?.[Math.floor((x+dx)/T)])return true;return false;}
function move(o,dx,dy,r=11){if(!solid(o.x+dx,o.y,r))o.x+=dx;if(!solid(o.x,o.y+dy,r))o.y+=dy;}
function lineClear(a,b){let d=dist(a,b);for(let i=0;i<d;i+=20){let t=i/d;if(solid(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t,2))return false;}return true;}
