function damagePlayer(amount,source){if(p.deathTime>0||p.hp<=0)return;if(p.dashTime>0){if(p.counterTime<=0||p.counterTime===undefined){p.counterTime=.85;floating(p.x,p.y,'회피 성공','#a4dec7');sound('dash',{volume:.38});}return;}if(p.invuln>0)return;let s=stats();amount=Math.max(1,Math.round(amount-s.armor));p.hp-=amount;p.invuln=.7;cancelPlayerAction();p.combo=0;p.comboWindow=0;startCombatAction(p,{name:'hurt',duration:.23,contact:.23,movement:.4,payload:{kind:'hurt'}});p.hitAngle=source?Math.atan2(p.y-source.y,p.x-source.x):p.angle+Math.PI;shake=5;hitstop=Math.max(hitstop,.055);floating(p.x,p.y,'−'+amount,'#ff827b');burst(p.x,p.y,'#cf5c56',10);sound('hurt');if(s.thorns)for(let e of entities)if(e.hp>0&&dist(e,p)<90)hit(e,s.thorns,10,true);if(p.hp<=0){if(s.revive&&!run.revived){run.revived=true;p.hp=s.hp*.5;p.invuln=3;circle(p.x,p.y,120,'#ffd690',1);notify('불사조의 깃털이 타올라 다시 일어납니다.');}else{cancelPlayerAction();p.deathTime=.8;startCombatAction(p,{name:'death',duration:.8,contact:.8,movement:0,payload:{kind:'death'}});clearInput();}}}
