function specializationSkill(){const h=hero();if(p.action||p.dashTime>0)return false;if(h.level<10||save.buildings.guild<1||!h.skills.ultimate){notify('전문화에는 10레벨과 길드 회관 1단계가 필요합니다.');return false;}if(p.c>0||p.mana<40)return false;p.angle=aim();startCombatAction(p,{name:'cast',duration:.64,contact:.24,movement:.4,payload:{kind:'specialization',angle:p.angle}});return true;}
