function drawEffects(){for(let f of effects){let a=clamp(f.life/f.max,0,1);ctx.save();ctx.globalAlpha=a;if(f.type==='particle')rect(f.x,f.y,f.size,f.size,f.color);if(f.type==='ring'||f.type==='blast'){ctx.strokeStyle=f.color;ctx.lineWidth=f.type==='blast'?8:3;ctx.beginPath();ctx.arc(f.x,f.y,f.r*(1-a*.45),0,TAU);ctx.stroke();if(f.type==='blast'){ctx.globalAlpha=a*.3;ctx.fillStyle=f.color;ctx.fill();}}if(f.type==='slash'){ctx.strokeStyle=f.color;ctx.lineWidth=10*a;ctx.beginPath();ctx.arc(f.x,f.y,f.r*.8,f.angle-1.1+(1-a),f.angle+.7+(1-a));ctx.stroke();ctx.strokeStyle='#fff0ce';ctx.lineWidth=2;ctx.stroke();}if(['zone','hostileZone','meteor'].includes(f.type)){ctx.globalAlpha=.12;ctx.fillStyle=f.color;ctx.beginPath();ctx.arc(f.x,f.y,f.r,0,TAU);ctx.fill();ctx.globalAlpha=f.type==='hostileZone'&&f.max-f.life<f.delay?.8:.4;ctx.strokeStyle=f.color;ctx.lineWidth=2;ctx.setLineDash([7,7]);ctx.stroke();ctx.setLineDash([]);if(f.type==='meteor'){ctx.globalAlpha=.8;ctx.beginPath();ctx.moveTo(f.x-45*a,f.y-220*a);ctx.lineTo(f.x,f.y);ctx.lineWidth=12*(1-a);ctx.stroke();}else for(let i=0;i<5;i++){let an=time+i*TAU/5;rect(f.x+Math.cos(an)*f.r*.7,f.y+Math.sin(an)*f.r*.7,3,3,f.color);}}if(f.type==='bolt'){ctx.strokeStyle=f.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(f.x,f.y);for(let i=1;i<6;i++){let a=i/6;ctx.lineTo(f.x+(f.x2-f.x)*a+Math.sin(i*5+time*50)*9,f.y+(f.y2-f.y)*a);}ctx.lineTo(f.x2,f.y2);ctx.stroke();}ctx.restore();}}
