function drawLegacyWarnings(){
 for(const e of entities){if(!e.active||e.hp<=0||!e.telegraph)continue;const warning=e.telegraph,active=warning.phase==='active';ctx.save();ctx.lineWidth=active?3:2;
  for(const shape of warning.shapes){const points=telegraphOutline(shape),information=shape.purpose==='information';ctx.fillStyle=information?'#8fcdd414':warning.color+'22';ctx.strokeStyle=information?'#8fcdd4':active?'#ffe6b5':warning.color;ctx.setLineDash(information?[3,7]:[]);ctx.beginPath();points.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();ctx.fill();ctx.stroke();}
  ctx.restore();
 }
}
